from research_helpers import *
A=ev('https://www.sec.gov/Archives/edgar/data/1041577/000104157714000003/atmi_20131231x10k.htm','ATMI2013 annual report directly names semiconductor product brands and life-science iCELLis/Xpansion; ViaForm manufactured by Enthone with ATMI marketing/distribution rights, not ATMI original manufacture.')
E=ev('https://www.entegris.com/en/home/about-us/news/news043014.html','ATMI acquired by Entegris April30 2014; later Entegris releases do not establish every later product was developed by historical ATMI.')
L=ev('https://www.sec.gov/Archives/edgar/data/1041577/000090951814000098/mm02-2114_8k.htm','LifeSciences assets sold to Pall on February20 2014, before semiconductor-company acquisition; parent rights end for life-science assets.')
P=ev('https://www.sec.gov/Archives/edgar/data/75829/000120677414000611/exhibit99-1.htm','Pall confirms acquired Integrity single-use technologies and Newform ultraclean sterile packaging, plus mixers and bioreactors.')
ps=[]
for name,desc,typ,roles in [('ATMI SDS3','Third-generation adsorbent-based subatmospheric dopant-gas delivery cylinder system.','product',['developer']),('ATMI VAC','Vacuum-actuated cylinder delivering ion-implant gases at subatmospheric pressure.','product',['developer']),('ATMI ProE-Vap','Delivery ampoule for low-volatility solid ALD precursors.','product',['developer']),('ATMI SAGE','Adsorbent-based semiconductor deposition-gas supply product family.','product',['developer']),('ATMI NOWPak','High-purity liner-based liquid chemical packaging and dispensing systems for chip fabrication.','product',['developer']),('ATMI BrightPak','Advanced photolithography liquid chemical containment and delivery system.','product',['developer']),('ATMI ST surface preparation chemicals','Proprietary semiconductor resist-strip and surface-preparation chemistry family.','product',['developer']),('ATMI AP surface preparation chemicals','Proprietary semiconductor cleaning chemistry family for surface preparation.','product',['developer']),('ViaForm','Enthone copper electrochemical-deposition chemistry marketed and distributed by ATMI.','product',['licensee','commercial_partner']),('ATMI Safe Delivery Source technology','Carbon-adsorption technology for safe subatmospheric semiconductor process-gas delivery.','technology',['developer'])]:
 ps.append(p(name,desc,A,typ=typ,roles=roles,sector='semiconductors',sub='materials_and_packaging' if name in ['ViaForm','ATMI ST surface preparation chemicals','ATMI AP surface preparation chemicals'] else 'semiconductor_equipment',attributes={'company_relationship_scope':'historical ATMI; acquired by Entegris2014','current_successor_lifecycle_unverified':True}))
for name,desc,typ in [('ATMI iCELLis','Historical fixed-bed bioreactor product family for adherent-cell bioprocessing.','product'),('ATMI Xpansion','Historical adherent-cell expansion bioreactor family.','product'),('ATMI Integrity single-use technologies','Historical single-use bioprocessing systems and consumables platform.','technology'),('ATMI Newform sterile packaging','Ultraclean sterile packaging for pharmaceutical and biopharmaceutical production.','product')]:
 ps.append(p(name,desc,A,typ=typ,sub='research_tools',valid_to='2014-02-20',evidence=[A,L,P],attributes={'company_relationship_scope':'historical ATMI developer; assets sold Pall February2014','current_successor_lifecycle_unverified':True}))
cs=[company('ATMI Inc',ps,[A,E,L,P],'Fourteen named historical semiconductor and bioprocessing products/technologies reviewed, with different acquisition histories preserved. ViaForm distributor role distinguished from manufacture. Exact formulation/model variants, additional bioreactors/mixers, current successor branding and ownership continuity remain to research; eVOLV metal recovery not automatically semiconductor/biotech product.')]
(out/'batch-0101.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
